import Foundation

extension Error {
    /// Cancellation (a torn-down `.task`, a scrolled-away image load) is an
    /// expected teardown, not a failure — callers skip logging it. Unwraps
    /// `NSUnderlyingErrorKey` so a cancellation wrapped by a framework error
    /// still matches.
    var isCancellation: Bool {
        if self is CancellationError { return true }
        if let urlError = self as? URLError, urlError.code == .cancelled { return true }
        if let underlying = (self as NSError).userInfo[NSUnderlyingErrorKey] as? Error {
            return underlying.isCancellation
        }
        return false
    }
}

