import Foundation

// MARK: - Protocol

/// Blog posts for the Home article rails, from the website's public
/// `/api/posts` feed. `LivePostsFeedService` fetches with plain URLSession —
/// deliberately not `APIClient`, which attaches Firebase auth and App Check
/// headers this public endpoint must not depend on. `MockPostsFeedService`
/// drives previews, snapshots, and unit tests.
protocol PostsFeedServiceSupporting: Sendable {
    /// The freshest feed available: the in-memory or persisted copy when
    /// younger than an hour and fetched for the current language, otherwise
    /// a network refresh that falls back to the persisted copy (or empty)
    /// on any failure. Never throws — the rails render whatever this
    /// returns and show no error state for feed problems.
    func articles() async -> [HomeArticle]
}

// MARK: - Live Implementation

actor LivePostsFeedService: PostsFeedServiceSupporting {

    /// Raw response body + fetch metadata, written to Application Support
    /// so offline launches render the rails and staleness survives
    /// relaunch. The body is re-decoded through the same path as fresh
    /// responses; `locale` is part of freshness — a fresh cache in the
    /// wrong language is stale.
    private struct PersistedFeed: Codable {
        let fetchedAt: Date
        let locale: String
        let body: Data
    }

    private struct LoadedFeed {
        let fetchedAt: Date
        let locale: String
        let feed: PostsFeed
    }

    private let feedURL: URL
    private let fetchData: @Sendable (URL) async throws -> (Data, URLResponse)
    private let cacheFileURL: URL
    private let now: @Sendable () -> Date
    private let preferredLocale: @Sendable () -> String
    /// Matches the server's `s-maxage=3600` — no point refreshing sooner.
    private let maxCacheAge: TimeInterval = 3600

    /// Once-per-process memo: disk is read at most once, and repeat Home
    /// appearances within the fresh window never touch disk or network.
    private var loaded: LoadedFeed?
    private var hasReadDisk = false

    init(
        feedURL: URL,
        // URLSession.shared's URLCache also honors the server's
        // Cache-Control, so even a forced refresh is usually cheap.
        fetchData: @escaping @Sendable (URL) async throws -> (Data, URLResponse) = {
            try await URLSession.shared.data(from: $0)
        },
        cacheFileURL: URL = URL.applicationSupportDirectory.appending(path: "PostsFeed/feed.json"),
        now: @escaping @Sendable () -> Date = { Date() },
        preferredLocale: @escaping @Sendable () -> String = { Locale.preferredLanguages.first ?? "en" }
    ) {
        self.feedURL = feedURL
        self.fetchData = fetchData
        self.cacheFileURL = cacheFileURL
        self.now = now
        self.preferredLocale = preferredLocale
    }

    func articles() async -> [HomeArticle] {
        if loaded == nil, !hasReadDisk {
            hasReadDisk = true
            loaded = loadPersisted()
        }
        let requested = preferredLocale()
        if let loaded, loaded.locale == requested,
           now().timeIntervalSince(loaded.fetchedAt) < maxCacheAge {
            return loaded.feed.posts
        }
        do {
            return try await refresh(requested: requested).posts
        } catch {
            // `.task` re-runs on the next appearance after a cancellation.
            if !error.isCancellation {
                Log.api.error("Posts feed refresh failed: \(error.localizedDescription)")
            }
            // Stale or wrong-language content beats empty rails.
            return loaded?.feed.posts ?? []
        }
    }

    // MARK: - Refresh

    private func refresh(requested: String) async throws -> PostsFeed {
        var components = URLComponents(url: feedURL, resolvingAgainstBaseURL: false)
        components?.queryItems = [URLQueryItem(name: "locale", value: requested)]
        let url = components?.url ?? feedURL

        let (data, response) = try await fetchData(url)
        if let http = response as? HTTPURLResponse, !(200..<300).contains(http.statusCode) {
            throw URLError(.badServerResponse)
        }
        let feed = try Self.decodeFeed(data)
        if feed.locale != requested {
            Log.api.info("Posts feed served locale \(feed.locale, privacy: .public) for requested \(requested, privacy: .public)")
        }
        loaded = LoadedFeed(fetchedAt: now(), locale: requested, feed: feed)
        persist(data, locale: requested)
        return feed
    }

    static func decodeFeed(_ data: Data) throws -> PostsFeed {
        try JSONDecoder().decode(PostsFeed.self, from: data)
    }

    // MARK: - Persistence

    private func loadPersisted() -> LoadedFeed? {
        guard let data = try? Data(contentsOf: cacheFileURL),
              let persisted = try? JSONDecoder().decode(PersistedFeed.self, from: data),
              let feed = try? Self.decodeFeed(persisted.body)
        else { return nil }
        return LoadedFeed(fetchedAt: persisted.fetchedAt, locale: persisted.locale, feed: feed)
    }

    /// Best-effort: a persistence failure only costs offline coverage.
    private func persist(_ body: Data, locale: String) {
        do {
            try FileManager.default.createDirectory(
                at: cacheFileURL.deletingLastPathComponent(),
                withIntermediateDirectories: true
            )
            let persisted = PersistedFeed(fetchedAt: now(), locale: locale, body: body)
            try JSONEncoder().encode(persisted).write(to: cacheFileURL, options: .atomic)
        } catch {
            Log.api.error("Posts feed persist failed: \(error.localizedDescription)")
        }
    }
}

