import Foundation
import Testing
@testable import SaveMyCactus

@Suite("Error.isCancellation")
struct ErrorCancellationTests {

    @Test func cancellationErrorMatches() {
        #expect(CancellationError().isCancellation)
    }

    @Test func cancelledURLErrorMatches() {
        #expect(URLError(.cancelled).isCancellation)
    }

    @Test func otherURLErrorsDoNotMatch() {
        #expect(!URLError(.timedOut).isCancellation)
        #expect(!URLError(.notConnectedToInternet).isCancellation)
    }

    @Test func wrappedCancellationMatches() {
        let wrapped = NSError(
            domain: "test.wrapper",
            code: 1,
            userInfo: [NSUnderlyingErrorKey: URLError(.cancelled)]
        )
        #expect(wrapped.isCancellation)
    }

    @Test func wrappedNonCancellationDoesNotMatch() {
        let wrapped = NSError(
            domain: "test.wrapper",
            code: 1,
            userInfo: [NSUnderlyingErrorKey: URLError(.timedOut)]
        )
        #expect(!wrapped.isCancellation)
    }

    @Test func unrelatedErrorDoesNotMatch() {
        struct SomeError: Error {}
        #expect(!SomeError().isCancellation)
    }
}

