import SwiftUI

// MARK: - Category Display Metadata

extension HomeArticle.Category {

    /// Section title and category chip label (display copy is the
    /// app's concern; the feed only ships machine keys).
    var displayName: String {
        switch self {
        case .careGuides: "Care guides"
        case .plantProblems: "Diseases and pests"
        case .gardenPlanning: "Garden planning"
        case .unknown: "More"
        }
    }

    /// SF Symbol drawn on the card's tinted canvas when a post has no
    /// cover image (or while one loads).
    var fallbackSymbolName: String {
        switch self {
        case .careGuides: "drop.fill"
        case .plantProblems: "ant.fill"
        case .gardenPlanning, .unknown: "leaf.fill"
        }
    }

    /// VoiceOver label for the rail's "See all" button. The catch-all
    /// rail is special-cased — "See all More" is not a sentence.
    var seeAllAccessibilityLabel: String {
        self == .unknown ? "See all articles" : "See all \(displayName)"
    }
}

/// Large image card in the horizontally scrolling Home article rails:
/// thumbnail canvas, category chip, title, read time. Tapping opens the
/// post in the in-app browser.
struct HomeArticleCard: View {

    @Environment(\.appTheme) private var theme

    let article: HomeArticle
    let action: () -> Void

    // Scales with Dynamic Type so 3 title lines keep fitting at XXL+.
    @ScaledMetric(relativeTo: .body) private var cardWidth: CGFloat = 260

    var body: some View {
        Button(action: action) {
            VStack(alignment: .leading, spacing: 12) {
                thumbnail
                VStack(alignment: .leading, spacing: 6) {
                    Text(article.title)
                        .font(IDKitFont.body.weight(.semibold))
                        .foregroundStyle(theme.label)
                        .multilineTextAlignment(.leading)
                        // Reserved even when the title is shorter, so every
                        // card in a rail is the same height and the read
                        // time sits at the same baseline across cards.
                        .lineLimit(3, reservesSpace: true)
                    Label("\(article.readingTime) min read", systemImage: "clock")
                        .font(IDKitFont.footnote)
                        .foregroundStyle(theme.textMuted)
                }
                .padding(.horizontal, 14)
                .padding(.bottom, 14)
            }
            // Cap the scaled width so an AX-size card never grows wider
            // than a phone screen — the title should wrap, not pan.
            .frame(width: min(cardWidth, 360), alignment: .leading)
            .contentShape(RoundedRectangle(cornerRadius: IDKitLayout.featureCardCornerRadius))
        }
        .buttonStyle(IDKitPressableButtonStyle(
            fill: AnyShapeStyle(theme.surface),
            cornerRadius: IDKitLayout.featureCardCornerRadius,
            border: AnyShapeStyle(theme.line)
        ))
        // The catch-all category's "More" reads like a stray word
        // mid-sentence in VoiceOver, so it is omitted there.
        .accessibilityLabel(
            article.category == .unknown
                ? "\(article.title), \(article.readingTime) minute read"
                : "\(article.title), \(article.category.displayName), \(article.readingTime) minute read"
        )
        .accessibilityHint("Opens the article in a browser inside the app")
    }

    /// Feed cover art when the post has one; the tinted SF-Symbol canvas
    /// is both the no-cover branch and the loading placeholder. Decorative
    /// throughout — the card's combined label is the accessible surface.
    private var thumbnail: some View {
        ZStack(alignment: .topLeading) {
            RoundedRectangle(cornerRadius: IDKitLayout.featureCardCornerRadius - 6)
                .fill(theme.surfaceTinted)
                .frame(height: 120)
                .overlay {
                    if let image = article.image {
                        // Symbol canvas crossfades into the cover —
                        // opacity-only, Reduce Motion safe.
                        AsyncImage(
                            url: image.src,
                            transaction: Transaction(animation: .easeOut(duration: 0.25))
                        ) { phase in
                            if let cover = phase.image {
                                cover
                                    .resizable()
                                    .scaledToFill()
                                    .transition(.opacity)
                            } else {
                                // One branch for every non-success phase keeps
                                // the placeholder's view identity stable, so
                                // empty → failure never animates the glyph
                                // against itself; `task(id:)` re-fires on that
                                // transition instead — one log per failed
                                // load attempt.
                                fallbackSymbol
                                    .task(id: coverLoadFailure(in: phase)) {
                                        guard let failure = coverLoadFailure(in: phase) else { return }
                                        Log.api.error("Article cover load failed for \(image.src.absoluteString, privacy: .public): \(failure, privacy: .public)")
                                    }
                            }
                        }
                        .frame(height: 120)
                        .frame(maxWidth: .infinity)
                        .clipShape(RoundedRectangle(cornerRadius: IDKitLayout.featureCardCornerRadius - 6))
                    } else {
                        fallbackSymbol
                    }
                }
            IDKitAccentPill(text: article.category.displayName)
                // The pill's translucent tint needs an opaque backing to
                // stay legible over arbitrary cover photos.
                .background(article.image == nil ? Color.clear : theme.surface, in: Capsule())
                .padding(8)
        }
        .padding(.horizontal, 6)
        .padding(.top, 6)
        .accessibilityHidden(true)
    }

    private var fallbackSymbol: some View {
        Image(systemName: article.category.fallbackSymbolName)
            .font(.system(size: 40, weight: .medium))
            .foregroundStyle(theme.accent)
    }

    /// Non-nil when the phase is a loggable failure: the error's description,
    /// which doubles as the `task(id:)` trigger that logs it.
    private func coverLoadFailure(in phase: AsyncImagePhase) -> String? {
        guard case .failure(let error) = phase, !error.isCancellation else { return nil }
        return String(describing: error)
    }
}

